import pytestimport pandas as pdfrom src.analysis import Analysis@pytest.fixturedef valid_dataframe():    data = {        'Date': ['2026-01-01', '2026-01-15', '2026-02-01', '2026-02-15', '2026-03-01'],        'Workout_Split': ['Chest/Triceps', 'Legs/Shoulders', 'Chest/Triceps', 'Back/Biceps', 'Legs/Shoulders'],        'Exercise': ['Bench Press', 'Squat', 'Bench Press', 'Pull-up', 'Squat'],        'Sets': [3, 4, 3, 3, 4],        'Reps': [10, 8, 12, 10, 8],        'Weight_kg': [80.0, 100.0, 85.0, 0.0, 110.0],  # Вес растет!        'RPE': [8.0, 9.0, 8.5, 7.0, 9.5],  # RPE тоже меняется        'Duration_min': [60, 70, 65, 50, 75]    }    return pd.DataFrame(data)@pytest.fixturedef invalid_dataframe():    data = {        'Date': ['2026-01-01'],        'Workout_Split': ['Chest'],        'Exercise': ['Bench Press'],        'Sets': ['Три'],  # Ошибка! Должно быть число        'Reps': [10],        'Weight_kg': [80.0],        'RPE': [8.0],        'Duration_min': [60]    }    return pd.DataFrame(data)def test_initialization_and_converter(valid_dataframe):    analys = Analysis(valid_dataframe)    assert 'Month_Number' in analys.df.columns    assert 'Year' in analys.df.columns    assert analys.df['Month_Number'].iloc[0] == 1    assert analys.df['Year'].iloc[0] == 2026def test_invalid_data_raises_error(invalid_dataframe):    with pytest.raises(ValueError, match="DataFrame columns have incorrect types"):        Analysis(invalid_dataframe)def test_max_weight_tonnage(valid_dataframe):    analys = Analysis(valid_dataframe)    analys.max_weight()    assert 'Tonnage' in analys.df.columns    # 3 сета * 10 повторов * 80 кг = 2400    first_row_tonnage = analys.df['Tonnage'].iloc[0]    assert first_row_tonnage == 2400.0def test_weight_stability_numpy_logic(valid_dataframe):    analys = Analysis(valid_dataframe)    result = analys.weight_stability('Bench Press')    # 80.0 и 85.0. ср. = 82.5    assert '82.5' in result    assert 'Упражнение: Bench Press' in resultdef test_weight_stability_empty_exercise(valid_dataframe):    analys = Analysis(valid_dataframe)    result = analys.weight_stability('Bicep Curl')    assert 'Нет данных' in resultdef test_hardcore_days_generator(valid_dataframe):    analys = Analysis(valid_dataframe)    generator = analys.get_hardcore_days(1)    hardcore_list = list(generator)    assert type(hardcore_list) == listdef test_pick_activiti_day(valid_dataframe):    analys = Analysis(valid_dataframe)    result = analys.pick_activiti()    # Самый жесткий день: 1 марта (110 кг * 4 * 8 = 3520 тоннаж, 75 минут)    assert '01.03.2026' in result    assert '3520' in result    assert '75' in resultdef test_hard_exercise_split_balance(valid_dataframe):    analys = Analysis(valid_dataframe)    result = analys.hard_exercise()    # Legs/Shoulders идут 70 и 75 минут (в ср. 72.5)    # А спина (Back/Biceps) всего 50 минут    assert 'Legs/Shoulders' in result    assert len(result) > 20def test_max_weight_best_month(valid_dataframe):    analys = Analysis(valid_dataframe)    result = analys.max_weight()    # Января (месяц 1)    # Bench Press: 3 * 10 * 80 = 2400    # Squat: 4 * 8 * 100 = 3200    # Суммарный тоннаж Января = 5600 кг.    assert '5600' in result    assert 'Январь' in result or '1' in resultdef test_max_weight_changes_progress(valid_dataframe):    analys = Analysis(valid_dataframe)    # 80.0 -> 85.0    bench_progress = analys.max_weight_changes('Bench Press', time_period=5)    assert bench_progress == 5.0 or 'No data' in str(bench_progress)def test_rpe_correlation(valid_dataframe):    analys = Analysis(valid_dataframe)    result = analys.rpe_correlation()    # тяжелые тренировки Squat (RPE 9.0 и 9.5)    assert 'Тяжёлая база' in result    assert 'RPE' in result